"""InvestigationWorkflow: the request's steps, generated by G2C for E2A v1.2 (declared steps under one
idempotency claim, taken before the first material step; a paused step resumes with resume())."""
import logging

from e2a import BaseWorkflow, Route, Step, Steps

from ..agents.intent_agent import IntentAgent
from ..agents.evidence_agent import EvidenceAgent
from ..agents.investigator_agent import InvestigatorAgent
from ..agents.proposal_agent import ProposalAgent
from ..agents.execution_agent import ExecutionAgent


class InvestigationWorkflow(BaseWorkflow):
    def __init__(self, agents=None) -> None:
        self.agents = agents or {'IntentAgent': IntentAgent(), 'EvidenceAgent': EvidenceAgent(), 'InvestigatorAgent': InvestigatorAgent(), 'ProposalAgent': ProposalAgent(), 'ExecutionAgent': ExecutionAgent()}

    def _build_workflow(self, ctx):
        return Steps(
            Step('route', self.agents['IntentAgent']),
            Step('gather', self.agents['EvidenceAgent']),
            Route('reason', by='intent', agents={'INVESTIGATE': self.agents['InvestigatorAgent'], 'EXPLAIN': self.agents['InvestigatorAgent'], 'PROPOSE': self.agents['ProposalAgent']}),
            Step('execute', self.agents['ExecutionAgent'], material=True),
        )

    def _generate_idempotency_key(self, state, ctx) -> str:
        raise NotImplementedError("decide what makes two requests the same request")  # TODO

    def _requires_idempotency_claim(self, state, ctx) -> bool:
        return True  # TODO: False for requests without a material effect

    def _handle_error(self, error, state, ctx):
        logging.error(f"[InvestigationWorkflow] {error}")
        state["status"] = "FAILED"
        state.setdefault("errors", []).append(str(error))
